import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.XctAhZuT.js";const i="/docs/images/authoring/_real/01-main-window.png",r="/docs/images/authoring/teacher-workflow.svg",l="/docs/images/authoring/_real/06-teacher-mode.png",n="/docs/images/authoring/_real/16-context-menu.png",I=JSON.parse('{"title":"教师指南","description":"完整逐步说明（含验收标准）在应用仓库 docs/authoring/teacher-guide.md。本文档聚焦 GUI 工具栏与课程树的对应关系。","frontmatter":{"description":"完整逐步说明（含验收标准）在应用仓库 docs/authoring/teacher-guide.md。本文档聚焦 GUI 工具栏与课程树的对应关系。"},"headers":[],"relativePath":"authoring/teacher-guide.md","filePath":"authoring/teacher-guide.md","lastUpdated":1789373514000}'),s={name:"authoring/teacher-guide.md"};function c(h,t,u,p,g,b){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="教师指南" tabindex="-1">教师指南 <a class="header-anchor" href="#教师指南" aria-label="Permalink to &quot;教师指南&quot;">​</a></h1><blockquote><p>面向不写代码的教师。目标：在本机完成一节 intro 课的产出、保存、教师试做与提交。不需要 Python / 命令行背景。</p></blockquote><p>完整逐步说明（含验收标准）在应用仓库 <code>docs/authoring/teacher-guide.md</code>。本文档聚焦 GUI 工具栏与课程树的对应关系。</p><p><img src="'+i+'" alt="Turna GUI 主界面（实际运行截图，加载 ）" loading="lazy"></p><p><img src="'+r+'" alt="教师产出一节 intro 课的六步流程与回退路径" loading="lazy"></p><p><img src="'+l+'" alt="教师模式试做：真实 Welcome 课的 multipleChoice 题型渲染" loading="lazy"></p><p><img src="'+n+`" alt="课程树右键菜单（实际运行截图：新增 / 删除 / AI 编辑 / AI 修正 / 预设）" loading="lazy"></p><h2 id="_0-准备" tabindex="-1">0. 准备 <a class="header-anchor" href="#_0-准备" aria-label="Permalink to &quot;0. 准备&quot;">​</a></h2><ol><li>从技术对接人处获得 <code>turna-gui</code>（或对应平台的可执行文件），双击运行。无需安装 Python。</li><li>取得课程目录副本（推荐本地副本，不要直接改团队共享目录）。例如 <code>我的课程/turkish/</code>。</li><li>启动后通过工具栏 <strong>「课程仓库 → 打开课程目录」</strong> 选定该目录。</li><li>状态栏显示 <code>已加载：&lt;路径&gt;</code> 即就绪。</li></ol><div class="tip custom-block"><p class="custom-block-title">团队协作</p><p>使用 <strong>「资源库 → Git 资源库」</strong> 接入远程仓库；不直接在共享目录写盘，避免覆盖别人未提交的修改。</p></div><h2 id="_1-gui-总览" tabindex="-1">1. GUI 总览 <a class="header-anchor" href="#_1-gui-总览" aria-label="Permalink to &quot;1. GUI 总览&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+----------------------------------------------------------------------------+</span></span>
<span class="line"><span>| [课程仓库] [保存] [课程工坊] [总览] [资源库] [发布] [生成听力音频]        |</span></span>
<span class="line"><span>| [教师模式] [设置]                                                          |</span></span>
<span class="line"><span>+----------------------------+-----------------------------------------------+</span></span>
<span class="line"><span>| 课程树 (Section/Unit/      | 详情面板（选中节点后）                       |</span></span>
<span class="line"><span>|  Lesson)                   |  - 元数据表单                                |</span></span>
<span class="line"><span>|                            |  - 课时编辑器 / 蓝图 / 题型表单              |</span></span>
<span class="line"><span>+----------------------------+-----------------------------------------------+</span></span>
<span class="line"><span>| 状态栏：就绪 | AI 校验防护激活中 | AI 生成内容仅供参考…  |  当前路径：…  |</span></span>
<span class="line"><span>+----------------------------------------------------------------------------+</span></span></code></pre></div><p>工具栏顺序、按钮文字、状态栏常驻提示均随上下文变化（见下节「教师模式 UI 变化」）。</p><h2 id="_2-产出一节-intro-课" tabindex="-1">2. 产出一节 intro 课 <a class="header-anchor" href="#_2-产出一节-intro-课" aria-label="Permalink to &quot;2. 产出一节 intro 课&quot;">​</a></h2><h3 id="_2-1-新建" tabindex="-1">2.1 新建 <a class="header-anchor" href="#_2-1-新建" aria-label="Permalink to &quot;2.1 新建&quot;">​</a></h3><ol><li>在目标 Unit 上右键 → <strong>新建 Lesson</strong>。</li><li>弹出模板选择，选 <strong>intro（认识新词）</strong>（如需 listening/reading/mastery 可走「功能课向导」三步产出）。</li><li>程序自动生成 id（<code>l-&lt;8 位随机 hex&gt;</code>），教师只填： <ul><li><code>name</code>：用户可见名称</li><li><code>description</code>：本课的可验证目标（一句话即可）</li><li><code>prerequisiteLessonIds</code>：同 Unit 内必须先完成的课</li></ul></li><li>点击「创建」。模板写入缺省的 canonical <code>content</code>： <ul><li><code>subLessons[0].stages[0]</code>：展示新词（<code>showWord</code>）</li><li><code>subLessons[0].stages[1]</code>：选择释义（<code>multipleChoice</code>）</li><li><code>subLessons[0].stages[2]</code>：填空巩固（<code>fillBlank</code>）</li></ul></li></ol><blockquote><p>若使用 <strong>「课程仓库 → 新建课程目录…」</strong> 一次性写出含样例内容的完整课程骨架，请参考 <a href="/docs/authoring/course-layout#新建议程目录">课程目录约定 - 新建议程目录</a>。</p></blockquote><h3 id="_2-2-填词" tabindex="-1">2.2 填词 <a class="header-anchor" href="#_2-2-填词" aria-label="Permalink to &quot;2.2 填词&quot;">​</a></h3><ul><li>词汇<strong>必须</strong>来自 <code>vocab.json</code>。<strong>禁止</strong>在 Lesson 内复制另一份词表。</li><li>题型表单的「词项」下拉关联到 <code>vocab.json.words[]</code>，按 ID 绑定。</li><li>干扰项从同范围同词性的真实易混项中选取，<strong>不要</strong>填入随机无关词。</li><li>释义以学习者母语写就；非空、不含占位文本。</li></ul><h3 id="_2-3-保存" tabindex="-1">2.3 保存 <a class="header-anchor" href="#_2-3-保存" aria-label="Permalink to &quot;2.3 保存&quot;">​</a></h3><ol><li>点击工具栏 <strong>「保存」</strong>（或 <code>Ctrl+S</code>）。</li><li>触发 <code>validate</code> + <code>lint</code>： <ul><li>通过：磁盘写盘，状态栏显示 <code>已保存</code>。</li><li>失败：状态栏显示 <code>校验失败，已回滚</code>；问题节点在课程树显示红角标；详情面板列出具体错误与 JSON Pointer 定位。</li></ul></li><li>修复后重新保存，<strong>不</strong>手动编辑 JSON。</li></ol><blockquote><p>仓库加载失败时弹「加载失败」对话框，下方 <strong>AI 分析</strong> 按钮调 LLM 给出可能根因与建议（详见 <a href="/docs/authoring/validation#ai-加载错误分析器">校验与 Lint - AI 加载错误分析器</a>）。该分析不替代结构性修复。</p></blockquote><h3 id="_2-4-教师试做" tabindex="-1">2.4 教师试做 <a class="header-anchor" href="#_2-4-教师试做" aria-label="Permalink to &quot;2.4 教师试做&quot;">​</a></h3><ol><li>点击工具栏 <strong>「教师模式」</strong>。</li><li>在桌面端模拟学员完整操作一遍： <ul><li>选词 / 填空 / 听音按钮</li><li>故意答错，验证反馈与错题归类</li><li>触发「下一课」与「复习」入口</li></ul></li><li>至少一次完整通过该 Lesson。<strong>不通过即视为未完成</strong>。</li></ol><p>详细试做对话框见下文「LessonPreviewDialog 流程」。</p><h3 id="_2-5-资源库联检" tabindex="-1">2.5 资源库联检 <a class="header-anchor" href="#_2-5-资源库联检" aria-label="Permalink to &quot;2.5 资源库联检&quot;">​</a></h3><p>打开工具栏 <strong>「资源库」</strong>，在该 Lesson 引用的每个词汇/表达/语法点上做一次跳转，确认：</p><ul><li>引用 ID 存在。</li><li><code>translation</code> 与释义一致。</li><li>无悬挂引用。</li></ul><h2 id="_3-课程树常用操作" tabindex="-1">3. 课程树常用操作 <a class="header-anchor" href="#_3-课程树常用操作" aria-label="Permalink to &quot;3. 课程树常用操作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>触发</th><th>备注</th></tr></thead><tbody><tr><td>新建</td><td>右键 → 新建</td><td>弹出模板选择；可走 FunctionalLessonWizard</td></tr><tr><td>复制</td><td><code>Ctrl+D</code></td><td>复制当前节点及其下级</td></tr><tr><td>重命名</td><td><code>F2</code></td><td>仅改 <code>name</code>，ID 不变</td></tr><tr><td>上移 / 下移</td><td><code>Ctrl+↑</code> / <code>Ctrl+↓</code></td><td>仅排序，不影响依赖</td></tr><tr><td>删除</td><td><code>Delete</code></td><td>二次确认；引用数 &gt; 0 时阻断</td></tr><tr><td>套用预设</td><td>多选 Lesson → 右键 → 批量套用预设…</td><td>替换为预设的题型组合（单课无此入口）</td></tr><tr><td>AI 编辑此节点</td><td>右键 → AI 编辑此 Section/Unit/Lesson</td><td>弹窗针对当前节点改写</td></tr><tr><td>AI 修正此节点</td><td>右键 → AI 修正</td><td>把当前节点的 validate 错误回灌给 LLM</td></tr><tr><td>批量操作</td><td><code>Ctrl</code> / <code>Shift</code> 多选后右键</td><td>复制 / 移动 / 套用预设 / 删除</td></tr><tr><td>撤销 / 重做</td><td><code>Ctrl+Z</code> / <code>Ctrl+Y</code></td><td>由 <code>QUndoStack</code> 驱动；上限在「设置 → 编辑器」配置</td></tr><tr><td>定位节点</td><td>总览点击 Lesson</td><td>总览与课程树双向跳转</td></tr></tbody></table><h2 id="_3-1-课程树右键菜单完整动作" tabindex="-1">3.1 课程树右键菜单完整动作 <a class="header-anchor" href="#_3-1-课程树右键菜单完整动作" aria-label="Permalink to &quot;3.1 课程树右键菜单完整动作&quot;">​</a></h2><p><code>tool/gui/src/widgets/course_tree.py::_build_context_menu</code> 提供按节点类型分组的菜单：</p><table tabindex="0"><thead><tr><th>节点</th><th>动作</th></tr></thead><tbody><tr><td>Section</td><td>新建 Unit / 删除 Section / AI 编辑此 Section / AI 修正此 Section</td></tr><tr><td>Unit</td><td>新建 Lesson / <strong>功能课向导…</strong> / 删除 Unit / AI 编辑此 Unit / AI 修正此 Unit</td></tr><tr><td>Lesson</td><td>复制 Lesson（<code>Ctrl+D</code>）/ 删除 Lesson / AI 编辑此 Lesson / AI 修正此 Lesson</td></tr><tr><td>选中多 Lesson</td><td>批量复制（N）/ 批量移动到…/ 批量套用预设…/ 批量删除（N）</td></tr></tbody></table><h3 id="_3-2-ai-动作完整清单" tabindex="-1">3.2 AI 动作完整清单 <a class="header-anchor" href="#_3-2-ai-动作完整清单" aria-label="Permalink to &quot;3.2 AI 动作完整清单&quot;">​</a></h3><p>课程树右键可触发的 8 个 AI 入口：</p><table tabindex="0"><thead><tr><th>入口</th><th>触发位置</th><th>行为</th></tr></thead><tbody><tr><td>AI 编辑此 Section</td><td>Section 右键</td><td>自由指令 + 4 类预设；走 <code>MergeAiSectionCommand</code></td></tr><tr><td>AI 编辑此 Unit</td><td>Unit 右键</td><td>自由指令 + 4 类预设；走 <code>AiEditUnitCommand</code></td></tr><tr><td>AI 编辑此 Lesson</td><td>Lesson 右键</td><td>自由指令 + 4 类预设；走 <code>AiEditLessonCommand</code></td></tr><tr><td>AI 修正此 Section</td><td>Section 右键</td><td>自动注入 Section 内 validate errors</td></tr><tr><td>AI 修正此 Unit</td><td>Unit 右键</td><td>同上，Unit 范围</td></tr><tr><td>AI 修正此 Lesson</td><td>Lesson 右键</td><td>同上，Lesson 范围</td></tr><tr><td>局部重生成</td><td>Unit / Lesson 右键（工坊内）</td><td>上下文收集 + 冲突解决；走 <code>MergeAiSectionCommand</code></td></tr><tr><td>试做 AI 改题</td><td>教师模式 → 题目 AI 按钮</td><td>单 Interaction 重生成；走 <code>AiEditLessonCommand</code></td></tr></tbody></table><p>校验面板与发布对话框另有 3 个 AI 入口（见 <a href="/docs/authoring/validation#ai-能力">校验与 Lint - AI 能力</a> 与 <a href="/docs/authoring/release-checklist#ai-能力">发布检查表 - AI 能力</a>）。</p><p>所有删除动作在引用数 &gt; 0 时弹二次确认；引用计数来自 <code>CourseAdapter</code> 全课程扫描。AI 节点编辑的具体语义见 <a href="/docs/authoring/lesson-schema#ai-节点编辑对话框">Lesson JSON 结构 - AI 节点编辑对话框</a>。</p><h2 id="_4-课程工坊-可选" tabindex="-1">4. 课程工坊（可选） <a class="header-anchor" href="#_4-课程工坊-可选" aria-label="Permalink to &quot;4. 课程工坊（可选）&quot;">​</a></h2><p>当产出方式以教材抽取或空白 AI 生成为主时：</p><ol><li>工具栏 <strong>「课程工坊」</strong> 打开非模态窗口。</li><li><strong>课本项目库</strong>（首次启动时显示）列出现有项目，可 <strong>从教材新建</strong> 或 <strong>空白 AI 项目</strong>。详见 <a href="/docs/authoring/textbook-import#课本项目库textbooklibrarydialog">教材导入 - 课本项目库</a>。</li><li>三栏画布： <ul><li>左栏：拖入教材或勾选入池的知识点</li><li>中栏：主题 / CEFR / 模板 / <code>Ctrl+Enter</code> 生成</li><li>右栏：结构大纲、试做、diff、AI 修复、导入</li></ul></li><li>草稿生成后<strong>必须</strong>逐课试做并人工校对。</li><li>导入成功后回到主窗口 <strong>保存</strong>。详见 <a href="/docs/authoring/textbook-import">教材导入</a>。</li></ol><h2 id="_5-资源库使用" tabindex="-1">5. 资源库使用 <a class="header-anchor" href="#_5-资源库使用" aria-label="Permalink to &quot;5. 资源库使用&quot;">​</a></h2><p>打开工具栏 <strong>「资源库」</strong> 进入三标签页：</p><ul><li><strong>vocab</strong>：词汇</li><li><strong>expressions</strong>：固定表达</li><li><strong>grammar_points</strong>：语法点</li></ul><p>操作：</p><ul><li>顶部搜索栏跨表过滤（大小写不敏感）。</li><li>双击行内任意列原地编辑。</li><li>多选行后批量删除。</li><li>导出 CSV → 翻译/校对外部编辑 → 导入 CSV（覆盖 / 合并 / 报错中断）。</li><li>「资源包」导出 / 导入整个 <code>vocab.json + expressions.json + grammar_points.json</code>。</li><li>删除前系统自动扫描引用；引用数 &gt; 0 阻断。</li></ul><h2 id="_6-提交给发布" tabindex="-1">6. 提交给发布 <a class="header-anchor" href="#_6-提交给发布" aria-label="Permalink to &quot;6. 提交给发布&quot;">​</a></h2><ol><li>工具栏 <strong>「发布」</strong> 触发 <code>PublishDialog</code>。详见 <a href="/docs/authoring/release-checklist#8-发布执行">发布检查表 - 8. 发布执行</a>。</li><li>专家模式显示 id-set diff、版本号变更复选框、音频 manifest totals；教师模式走 <code>humanize_problem</code> 翻译。</li><li>全绿后导出 Markdown 发布报告。</li><li>把报告与变更 commit 一起提交。</li></ol><h2 id="_7-常见约束" tabindex="-1">7. 常见约束 <a class="header-anchor" href="#_7-常见约束" aria-label="Permalink to &quot;7. 常见约束&quot;">​</a></h2><table tabindex="0"><thead><tr><th>约束</th><th>原因</th><th>处置</th></tr></thead><tbody><tr><td>每 Section ≤ 60 Unit</td><td>移动端首屏渲染</td><td>拆分 Section</td></tr><tr><td>每 Unit ≤ 40 Lesson</td><td>复习调度计算量</td><td>拆分 Unit</td></tr><tr><td>先修只在同 Unit 内</td><td>跨层依赖在更高层声明</td><td>调整所属 Unit</td></tr><tr><td>听力课必须有音频</td><td>manifest 校验</td><td>先做 intro / practice，再补听力</td></tr><tr><td>词汇必须来自 vocab.json</td><td>引用闭环</td><td>在资源库补建</td></tr></tbody></table><h2 id="_8-故障与求助" tabindex="-1">8. 故障与求助 <a class="header-anchor" href="#_8-故障与求助" aria-label="Permalink to &quot;8. 故障与求助&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处置</th></tr></thead><tbody><tr><td>保存按钮灰</td><td>存在 validate error；打开校验面板修复</td></tr><tr><td>课程树节点红角标</td><td>点击红角标查看具体错误</td></tr><tr><td>资源引用红色警示</td><td>资源已被删除或拼写错误；用资源库补建或替换</td></tr><tr><td>音频播放异常</td><td>见 <a href="/docs/authoring/audio-assets">音频资产</a> QA 清单</td></tr><tr><td>工坊抽取失败</td><td>走 OCR 流程或换预设重试</td></tr></tbody></table><h2 id="_9-不做的事" tabindex="-1">9. 不做的事 <a class="header-anchor" href="#_9-不做的事" aria-label="Permalink to &quot;9. 不做的事&quot;">​</a></h2><ul><li>不直接编辑磁盘 JSON 绕过校验。</li><li>不在 Lesson 内复制整份词表。</li><li>不修改已发布 ID。</li><li>不在 Lesson 内使用扁平 <code>questions</code>（新内容）。</li><li>不在共享目录直接写盘。</li><li>不删除有引用的资源。</li><li>不在保存失败时强行覆盖。</li></ul><h2 id="a-教师模式-ui-变化" tabindex="-1">A. 教师模式 UI 变化 <a class="header-anchor" href="#a-教师模式-ui-变化" aria-label="Permalink to &quot;A. 教师模式 UI 变化&quot;">​</a></h2><p>工具栏 <strong>「教师模式」</strong> 是一个 <code>QCheckAction</code>（<code>app.py::_on_mode_toggled</code>）。切换后以下元素变化：</p><details class="details custom-block"><summary>逐项对照</summary><table tabindex="0"><thead><tr><th>元素</th><th>关闭</th><th>开启</th></tr></thead><tbody><tr><td>工具栏按钮文字</td><td>教师模式</td><td>教师模式：开</td></tr><tr><td>窗口标题</td><td>Turna 课程编辑器</td><td>Turna 课程编辑器 · 教师模式</td></tr><tr><td>详情面板渲染</td><td><code>DetailPanel</code> 直接渲染</td><td>走 <code>teacher_view_model</code> 隐藏高级字段</td></tr><tr><td><code>runtimeType</code> 标签</td><td>英文枚举（<code>multipleChoice</code>）</td><td>中文标签（选择题）</td></tr><tr><td>AI 按钮</td><td>全部显示</td><td>默认隐藏；按权限分级显示</td></tr><tr><td>状态栏常驻提示</td><td><code>AI 校验防护激活中</code></td><td>替换为 <code>教师模式：试做中</code></td></tr></tbody></table><p><code>teacher_view_model.TeacherViewModel</code>（<code>tool/gui/src/backend/teacher_view_model.py</code>）按节点类型给出视图投影：教师模式下，题目的答案字段（<code>correctIndex</code> / <code>correctIndices</code> / <code>answer</code> 等）不被渲染到 UI；学员提交答案后才显示对错。</p></details><h2 id="b-lessonpreviewdialog-流程" tabindex="-1">B. LessonPreviewDialog 流程 <a class="header-anchor" href="#b-lessonpreviewdialog-流程" aria-label="Permalink to &quot;B. LessonPreviewDialog 流程&quot;">​</a></h2><p><code>tool/gui/src/teacher/preview_window.py:252</code> 实现的 <code>LessonPreviewDialog</code> 提供 Lesson 级试做视图。入口：</p><ul><li>教师模式 → 课程树右键 → <strong>试做此 Lesson</strong>。</li><li>教师模式 → 详情面板右上角 <strong>试做</strong> 按钮。</li><li>教师模式 → 总览点击 Lesson 卡片 → 弹窗预览。</li></ul><details class="details custom-block"><summary>预览区域与题型支持</summary><table tabindex="0"><thead><tr><th>区域</th><th>内容</th></tr></thead><tbody><tr><td>顶部</td><td>Lesson 名称 / <code>template</code> 中文标签 / 总进度 <code>3/12</code></td></tr><tr><td>中部</td><td>当前 Interaction 渲染（按 <code>runtimeType</code> 调对应 widget）</td></tr><tr><td>底部</td><td>上一题 / 下一题 / 重新开始 / 显示答案（仅教师模式）</td></tr><tr><td>右上角</td><td>退出试做 → 关闭对话框返回主窗口</td></tr></tbody></table><p>支持 <code>runtimeType</code> 渲染：<code>showWord</code> / <code>multipleChoice</code> / <code>multiSelect</code> / <code>fillBlank</code> / <code>translateSentence</code> / <code>reorderSentence</code> / <code>typeTheWord</code> / <code>listenAndPick</code> / <code>listenOnly</code> / <code>readingMcq</code> / <code>readingTrueFalse</code> / <code>readingShortAnswer</code> / <code>ankiCard</code> / <code>ankiHtmlCard</code>（共 14 种；Anki 两种在桌面是降级预览 —— <code>ankiCard</code> 显示为普通翻卡，<code>ankiHtmlCard</code> 显示剥标签文本 + 「App 渲染为准」标记）。试做结束不写盘；纯运行时模拟。</p></details><h2 id="c-状态栏与全局通知" tabindex="-1">C. 状态栏与全局通知 <a class="header-anchor" href="#c-状态栏与全局通知" aria-label="Permalink to &quot;C. 状态栏与全局通知&quot;">​</a></h2><p><code>QStatusBar</code> 固定 28px 高，分三段：</p><details class="details custom-block"><summary>三段对照</summary><table tabindex="0"><thead><tr><th>段</th><th>内容</th><th>来源</th></tr></thead><tbody><tr><td>左</td><td>当前操作状态（如「已加载: assets/courses/turkish」、「校验失败，已回滚」）</td><td>业务调用 <code>statusBar().showMessage(msg, timeout)</code></td></tr><tr><td>中</td><td>AI 校验防护 / 撤销 / 复制粘贴 等临时提示</td><td><code>_on_status</code> 回调</td></tr><tr><td>右</td><td>永久挂载的免责声明「AI 生成内容仅供参考，请作者自行审核其准确性与适用性。」</td><td><code>app.py::_build_status_bar</code></td></tr></tbody></table></details><p><code>telemetry</code> 事件贯穿所有写盘动作；<code>操作日志</code> 标签页（设置第 8 个 tab）可回看最近 200 条操作。</p><h2 id="ai-协作模式" tabindex="-1">AI 协作模式 <a class="header-anchor" href="#ai-协作模式" aria-label="Permalink to &quot;AI 协作模式&quot;">​</a></h2><p>教师在 GUI 中可以 8 处主动调用 AI，也可以选择不调用。本节给出<strong>何时用 / 何时不用 / 何时绝对不下放</strong>的边界。</p><h3 id="何时用-ai" tabindex="-1">何时用 AI <a class="header-anchor" href="#何时用-ai" aria-label="Permalink to &quot;何时用 AI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>入口</th><th>体感</th></tr></thead><tbody><tr><td>教材抽取后批量生成草稿</td><td>工坊 → 从教材新建 → 抽章 → Grounded 生成</td><td>减少手工拼装 Lesson 的时间</td></tr><tr><td>空白项目冷启动</td><td>工坊 → 空白 AI 项目 → 主题/等级 → 快速/精修</td><td>无需从零手写 canonical content</td></tr><tr><td>课程树右键局部润色</td><td>树右键 → AI 编辑此 Lesson/Unit</td><td>4 类预设指令或自由指令</td></tr><tr><td>试做时改题</td><td>教师模式 → 题目 → AI 按钮</td><td>局部重生成 + diff 预览</td></tr><tr><td>校验清零</td><td>校验面板多选 → AI 自动修正</td><td>不必逐条点修</td></tr><tr><td>加载失败诊断</td><td>加载失败弹窗 → AI 分析</td><td>拟人化解释堆栈</td></tr><tr><td>工坊任务失败</td><td>失败弹窗 → 拟人化分析</td><td>给可能根因 + 修复建议</td></tr><tr><td>总览看低分节</td><td>总览 → Section 卡片 → AI 修复</td><td>按六维质量分定向</td></tr></tbody></table><h3 id="何时不用-ai" tabindex="-1">何时不用 AI <a class="header-anchor" href="#何时不用-ai" aria-label="Permalink to &quot;何时不用 AI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>原因</th></tr></thead><tbody><tr><td>发布前的最终人工审定</td><td>校验与 lint 是结构性，AI 不替代作者审校</td></tr><tr><td>听力音频的人工录音决定</td><td>录音由作者或母语者完成；TTS 不可替代</td></tr><tr><td>关键先修依赖的拓扑设计</td><td>跨 Lesson 解锁与 FSRS 调度由作者设计；AI 改写拓扑易破坏复习曲线</td></tr><tr><td>资源 ID 的最终命名</td><td>ID 是引用锚点；AI 命名易冲突</td></tr><tr><td>真实图片 / 视频的选用</td><td>AI 不可访问真实媒体库；选用决策由作者完成</td></tr></tbody></table><h3 id="教师不下放-ai-的边界" tabindex="-1">教师不下放 AI 的边界 <a class="header-anchor" href="#教师不下放-ai-的边界" aria-label="Permalink to &quot;教师不下放 AI 的边界&quot;">​</a></h3><p>硬规则，违反任一条的 AI 输出必须由作者裁决，不得静默应用：</p><ol><li>不让 AI 改既有节点的 <code>id</code>（包括 <code>l-</code> / <code>u-</code> / <code>s-</code> / <code>w-</code> / <code>e-</code> / <code>g-</code> 前缀的）。</li><li>不让 AI 删既有 <code>vocab</code> / <code>expression</code> / <code>grammar_point</code>。</li><li>不让 AI 自动覆盖既有 Section（必须人工选合并 / 跳过 / 覆盖 / 作为新 Section）。</li><li>不让 AI 在共享目录自动写盘（仅在 <code>course_dir</code> 内允许）。</li><li>不让 AI 在没有作者 review 的情况下进入发布。</li><li>不让 AI 跳过 <code>validate</code> 与 <code>lint</code>。</li><li>不让 AI 替换为未注册的 <code>runtimeType</code>。</li><li>不让 AI 跨越语言对边界（如 <code>tr</code> 课程引用 <code>en</code> 课程的 <code>vocab</code>）。</li></ol><p>GUI 在上述边界处会拒绝 AI 写入并提示冲突；详见 <a href="/docs/authoring/ai-course-generation#8-创作者不下放的边界">AI 课程生成 - 创作者不下放的边界</a>。</p><h3 id="_3-3-模式与不下放的对应" tabindex="-1">3.3 模式与不下放的对应 <a class="header-anchor" href="#_3-3-模式与不下放的对应" aria-label="Permalink to &quot;3.3 模式与不下放的对应&quot;">​</a></h3><p>AI 的「下不下放」由 4 档体验模式控制。<code>observer</code> 模式下任何 AI 写动作均被拒绝；<code>copilot</code> 默认安全；<code>active</code> 启用 ambient / soft / defer 套装；<code>immersive</code> 允许白名单静默执行（出站操作仍拒绝），<code>Ctrl+Shift+D</code> 随时降档回 <code>copilot</code>。完整决策矩阵见 <a href="/docs/authoring/ai-control-modes#7-决策矩阵模式--能力">AI 控制模式 - 决策矩阵</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/docs/authoring/course-layout">课程目录约定</a></li><li><a href="/docs/authoring/lesson-schema">Lesson JSON 结构</a></li><li><a href="/docs/authoring/resource-files">资源文件</a></li><li><a href="/docs/authoring/validation">校验与 Lint</a></li><li><a href="/docs/authoring/textbook-import">教材导入</a></li><li><a href="/docs/authoring/release-checklist">发布检查表</a></li><li><a href="/docs/guide/lesson-types">课型说明</a></li></ul>`,79)])])}const _=e(s,[["render",c]]);export{I as __pageData,_ as default};
